(() => {
  "use strict";

  const allowedCases = new Set([
    "peer-spacing-clean",
    "peer-spacing-mutant",
    "out-of-viewport-mutant",
    "intentional-grouping",
    "ambiguous-peer-group",
    "clipping-mutant",
    "control-clip-mutant",
    "control-boundaries",
    "control-offscreen-mutant",
    "ambiguous-control",
    "intentional-overlay",
    "notification-clean",
    "occlusion-clean",
    "occlusion-mutant",
    "overflow-mutant",
    "peer-dimension-mutant",
    "responsive-mobile-mutant",
    "rtl-vertical",
    "transformed-text-mutant",
    "unnamed-control-mutant",
    "scrollable-control-hard-negative",
  ]);
  const parameters = new URLSearchParams(window.location.search);
  const requestedCase = parameters.get("case") || "peer-spacing-clean";
  const fixtureCase = allowedCases.has(requestedCase) ? requestedCase : "peer-spacing-clean";
  const requestedTextScale = Number(parameters.get("textScale") || "1");
  const textScale = requestedTextScale === 1.25 ? 1.25 : 1;

  document.body.dataset.case = fixtureCase;
  document.documentElement.dir = fixtureCase === "rtl-vertical" ? "rtl" : "ltr";
  document.documentElement.style.fontSize = `${16 * textScale}px`;
  if (fixtureCase === "unnamed-control-mutant") {
    document.querySelector("[data-testid='help-action']")?.removeAttribute("aria-label");
  }
  document.documentElement.dataset.fixtureReady = "true";

  Object.defineProperty(window, "__SIGHTLINT_FIXTURE__", {
    configurable: false,
    enumerable: true,
    writable: false,
    value: Object.freeze({
      caseId: fixtureCase,
      textScale,
      externalAssets: false,
      ready: true,
    }),
  });
})();

:root {
  color-scheme: light;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  color: #172033;
  background: #f3f5f9;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: #f3f5f9;
}

button,
a {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  min-height: 100vh;
}

.sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 32px;
  height: 100vh;
  padding: 28px 20px;
  color: #f8fafc;
  background: #172033;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  color: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  text-decoration: none;
}

.brand-mark {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 10px;
  color: #172033;
  background: #8ee3c3;
}

nav {
  display: grid;
  gap: 8px;
}

.nav-item {
  padding: 10px 12px;
  border-radius: 9px;
  color: #b9c2d3;
  text-decoration: none;
}

.nav-item-active {
  color: #ffffff;
  background: #28344d;
}

.sidebar-note {
  display: grid;
  gap: 6px;
  margin-top: auto;
  padding: 14px;
  border: 1px solid #34415c;
  border-radius: 12px;
  color: #d8deea;
  font-size: 0.75rem;
}

.sidebar-note span {
  color: #9faac0;
}

.main-content {
  width: min(1100px, 100%);
  margin: 0 auto;
  padding: 48px;
}

.page-header,
.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.page-header {
  margin-bottom: 40px;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 10px;
  font-size: 2rem;
  line-height: 1.15;
}

h2 {
  margin-bottom: 0;
  font-size: 1.25rem;
}

h3 {
  margin-bottom: 20px;
  font-size: 1rem;
  line-height: 1.35;
}

.eyebrow {
  margin-bottom: 8px;
  color: #68758c;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.lede {
  margin-bottom: 0;
  color: #68758c;
}

.primary-action,
.quiet-action {
  min-height: 42px;
  padding: 0 18px;
  border-radius: 10px;
  font-weight: 700;
}

.primary-action {
  border: 1px solid #245f50;
  color: #ffffff;
  background: #287b66;
}

.quiet-action {
  border: 1px solid #d3d9e4;
  color: #33405a;
  background: #ffffff;
}

.metrics-stage {
  margin-top: 20px;
}

.metric-peer-group {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

.metric-card,
.promotion-card,
.activity-panel {
  border: 1px solid #dfe4ec;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgb(31 42 66 / 6%);
}

.metric-card,
.promotion-card {
  min-height: 160px;
  padding: 22px;
}

.metric-card {
  align-self: start;
}

.metric-label {
  margin-bottom: 18px;
  color: #68758c;
  font-size: 0.8125rem;
  font-weight: 700;
}

.metric-value {
  margin-bottom: 12px;
  font-size: 1.75rem;
  font-weight: 750;
  letter-spacing: -0.03em;
}

.metric-trend {
  margin-bottom: 0;
  color: #68758c;
  font-size: 0.8125rem;
}

.metric-trend-positive {
  color: #287b66;
}

.promotion-card {
  display: none;
}

body[data-case="peer-spacing-mutant"] .metric-card-third {
  transform: translateX(16px);
}

body[data-case="out-of-viewport-mutant"] .metric-card:first-child {
  transform: translateX(-320px);
}

body[data-case="intentional-grouping"] .metrics-stage {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(220px, 1fr);
  gap: 40px;
}

body[data-case="intentional-grouping"] .metric-peer-group {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

body[data-case="intentional-grouping"] .metric-card-third {
  display: none;
}

body[data-case="intentional-grouping"] .promotion-card {
  display: block;
}

body[data-case="ambiguous-peer-group"] .metric-card-third {
  margin-left: 16px;
  border-style: dashed;
}

.promotion-card a {
  color: #245f50;
  font-weight: 700;
}

.activity-panel {
  margin-top: 32px;
  padding: 24px;
}

.status-pill {
  padding: 7px 10px;
  border-radius: 999px;
  color: #236451;
  background: #e2f5ee;
  font-size: 0.75rem;
  font-weight: 700;
}

.activity-list {
  margin-top: 18px;
  border-top: 1px solid #e5e9f0;
}

.activity-row {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid #e5e9f0;
}

.activity-row p {
  margin: 4px 0 0;
  color: #68758c;
  font-size: 0.875rem;
}

.avatar {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  color: #263349;
  background: #dbe8ff;
  font-size: 0.75rem;
  font-weight: 700;
}

.avatar-coral {
  background: #ffe1d8;
}

.avatar-green {
  background: #d8f3e9;
}

.activity-time {
  color: #7b879b;
  font-size: 0.75rem;
}

.operations-panel {
  position: relative;
  margin-top: 32px;
  padding: 24px;
  border: 1px solid #dfe4ec;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgb(31 42 66 / 6%);
}

.queue-label {
  color: #526078;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.operations-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(280px, 0.75fr);
  gap: 24px;
  margin-top: 20px;
}

.notification-viewport {
  overflow: hidden;
  border: 1px solid #dfe4ec;
  border-radius: 12px;
  background: #f8fafc;
}

.notification-card {
  width: 100%;
  min-height: 164px;
  padding: 20px;
  background: #f8fafc;
}

.notification-title {
  margin-bottom: 10px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.notification-copy {
  margin-bottom: 0;
  color: #68758c;
  font-size: 0.875rem;
}

.control-boundaries {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}

.compact-visual-card {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px;
  border: 1px solid #d3d9e4;
  border-radius: 12px;
  color: #33405a;
  background: #ffffff;
  font-size: 0.8125rem;
  font-weight: 700;
}

.compact-hit-action {
  min-width: 42px;
  min-height: 30px;
  border: 1px solid #c4ccd9;
  border-radius: 8px;
  color: #33405a;
  background: #f8fafc;
}

.large-hit-action {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  border: 1px solid #c4ccd9;
  border-radius: 12px;
  color: #245f50;
  background: #eef9f5;
}

.help-action {
  display: none;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid #c4ccd9;
  border-radius: 10px;
  color: #33405a;
  background: #ffffff;
  font-weight: 800;
}

body[data-case="control-boundaries"] .help-action,
body[data-case="unnamed-control-mutant"] .help-action {
  position: fixed;
  z-index: 4;
  top: 300px;
  right: 48px;
  display: grid;
}

.small-visual-glyph {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  color: #ffffff;
  background: #287b66;
  font-weight: 700;
}

.control-boundaries > button:not(.large-hit-action, .compact-hit-action) {
  min-height: 38px;
  border: 1px solid #c4ccd9;
  border-radius: 8px;
  background: #ffffff;
}

.disclosure-action {
  display: none;
}

.review-action-wrap {
  position: relative;
  width: max-content;
  margin-top: 20px;
}

.accidental-blocker,
.intentional-popover,
.control-clip-viewport,
.ambiguous-action {
  display: none;
}

.control-clip-viewport {
  width: 176px;
  height: 52px;
  border: 1px solid #c4ccd9;
  border-radius: 10px;
  background: #f8fafc;
}

.clipped-action {
  width: 148px;
  height: 40px;
  margin: 5px 0 0 -24px;
  border: 1px solid #245f50;
  border-radius: 8px;
  color: #ffffff;
  background: #287b66;
}

.ambiguous-action {
  padding: 12px 16px;
  border: 1px dashed #7b879b;
  border-radius: 10px;
  color: #33405a;
  background: #ffffff;
}

body[data-case="clipping-mutant"] .notification-card {
  transform: translateX(300px);
}

body[data-case="clipping-mutant"] .notification-viewport,
body[data-case="notification-clean"] .notification-viewport,
body[data-case="overflow-mutant"] .notification-viewport {
  position: fixed;
  z-index: 3;
  top: 520px;
  left: 360px;
  width: 560px;
}

body[data-case="overflow-mutant"] .notification-title {
  width: 148px;
}

body[data-case="peer-dimension-mutant"] .metric-card-third {
  min-height: 208px;
}

body[data-case="transformed-text-mutant"] .metric-card-third .metric-value {
  transform: scale(0.65);
  transform-origin: left center;
}

body[data-case="occlusion-mutant"] .accidental-blocker {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #7a2e2e;
  background: rgb(255 225 216 / 96%);
  font-size: 0.75rem;
  font-weight: 700;
}

body[data-case="occlusion-mutant"] .review-action-wrap,
body[data-case="occlusion-clean"] .review-action-wrap,
body[data-case="intentional-overlay"] .review-action-wrap {
  position: fixed;
  z-index: 3;
  top: 132px;
  left: 760px;
  margin-top: 0;
}

body[data-case="intentional-overlay"] .intentional-popover {
  position: absolute;
  z-index: 2;
  inset: -8px;
  display: grid;
  width: 170px;
  min-height: 58px;
  padding: 14px;
  border: 1px solid #c4ccd9;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgb(31 42 66 / 16%);
}

body[data-case="control-boundaries"] .control-clip-viewport,
body[data-case="control-clip-mutant"] .control-clip-viewport,
body[data-case="scrollable-control-hard-negative"] .control-clip-viewport {
  position: fixed;
  z-index: 3;
  top: 360px;
  right: 48px;
  display: block;
  overflow: visible;
}

body[data-case="control-clip-mutant"] .control-clip-viewport {
  overflow: hidden;
}

body[data-case="scrollable-control-hard-negative"] .control-clip-viewport {
  overflow: auto;
}

body[data-case="ambiguous-control"] .ambiguous-action {
  position: fixed;
  z-index: 3;
  top: 360px;
  right: 48px;
  display: block;
}

body[data-case="intentional-overlay"] .intentional-popover p {
  margin: 6px 0 0;
  color: #68758c;
  font-size: 0.8125rem;
}

body[data-case="control-offscreen-mutant"] .offscreen-action {
  transform: translateX(-1800px);
}

body[data-case="control-boundaries"] .control-boundaries,
body[data-case="control-offscreen-mutant"] .control-boundaries,
body[data-case="unnamed-control-mutant"] .control-boundaries {
  position: fixed;
  z-index: 3;
  top: 116px;
  right: 48px;
  width: 360px;
  padding: 16px;
  border: 1px solid #c4ccd9;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgb(31 42 66 / 16%);
}

body[data-case="rtl-vertical"] .queue-label {
  position: fixed;
  z-index: 3;
  top: 116px;
  right: 48px;
  padding: 10px;
  border-radius: 8px;
  background: #e2f5ee;
  writing-mode: vertical-rl;
}

body[data-case="responsive-mobile-mutant"] .metric-card:first-child {
  transform: translateX(-360px);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 760px) {
  .app-shell {
    display: block;
  }

  .sidebar {
    position: static;
    display: block;
    height: auto;
    padding: 18px 20px;
  }

  .sidebar nav,
  .sidebar-note {
    display: none;
  }

  .main-content {
    padding: 28px 20px;
  }

  .page-header,
  .section-heading {
    align-items: flex-start;
  }

  .page-header {
    flex-direction: column;
    margin-bottom: 32px;
  }

  .metric-peer-group,
  body[data-case="intentional-grouping"] .metrics-stage {
    display: grid;
    grid-template-columns: 1fr;
    gap: 16px;
  }

  body[data-case="peer-spacing-mutant"] .metric-card-third {
    transform: translateY(16px);
  }

  body[data-case="out-of-viewport-mutant"] .metric-card:first-child {
    transform: translateX(-320px);
  }

  .activity-row {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .activity-time {
    grid-column: 2;
  }

  .operations-grid {
    grid-template-columns: 1fr;
  }

  body[data-case="clipping-mutant"] .notification-card {
    transform: translateX(180px);
  }

  body[data-case="clipping-mutant"] .notification-viewport,
  body[data-case="notification-clean"] .notification-viewport,
  body[data-case="overflow-mutant"] .notification-viewport {
    top: 520px;
    left: 20px;
    width: 300px;
  }

  body[data-case="responsive-mobile-mutant"] .metric-card:first-child {
    transform: translateX(-360px);
  }
}

